reduced.addEventListener('change',()=>{updateSlide();schedule()});document.addEventListener('visibilitychange',schedule);
async function loadPortraits(){try{const response=await fetch('portraits.json');if(!response.ok)throw Error('Portrait configuration unavailable');const entries=await response.json();const loaded=await Promise.all(entries.map(p=>new Promise(resolve=>{const image=new Image();image.onload=()=>resolve({...p,image});image.onerror=()=>resolve(null);image.src=p.src})));portraits=loaded.filter(Boolean);portraits.forEach((p,i)=>{p.image.className='portrait';p.image.alt='';$('#portraits').append(p.image);const dot=document.createElement('button');dot.onclick=()=>{slide=i;updateSlide();schedule()};$('#dots').append(dot)});$('#home').classList.toggle('has-portraits',portraits.length>0);$('#carousel').hidden=portraits.length<2;fitPortraits();updateSlide();schedule()}catch(e){console.warn('Portraits not loaded:',e.message)}}

// Reserve the area above the overlay copy for each face, then cover the full hero.
function fitPortraits(){const frame=$('#portraits'),width=frame.clientWidth,height=frame.clientHeight;if(!width||!height||!portraits.length)return;const clamp=(v,min,max)=>Math.min(max,Math.max(min,v));portraits.forEach(p=>{const iw=p.image.naturalWidth,ih=p.image.naturalHeight,[x,y,w,h]=p.face||[.4,.25,.2,.25],scale=Math.max(width/iw,height/ih),rw=iw*scale,rh=ih*scale;let left=clamp(width*.5-(x+w/2)*rw,width-rw,0),top=clamp(height*.42-(y+h/2)*rh,height-rh,0);const label=$('.hero-name'),safeBottom=label?Math.min(height,label.getBoundingClientRect().top-frame.getBoundingClientRect().top-18):height;const minX=Math.max(width-rw,10-x*rw),maxX=Math.min(0,width-10-(x+w)*rw),minY=Math.max(height-rh,-y*rh),maxY=Math.min(0,safeBottom-(y+h)*rh);if(minX<=maxX)left=clamp(left,minX,maxX);if(minY<=maxY)top=clamp(top,minY,maxY);p.image.style.width=rw+'px';p.image.style.height=rh+'px';p.image.style.left=left+'px';p.image.style.top=top+'px';p.image.dataset.faceBounds=JSON.stringify([left+x*rw,top+y*rh,w*rw,h*rh])})}
const portraitResize=new ResizeObserver(fitPortraits);portraitResize.observe($('#portraits'));portraitResize.observe($('.hero-content'));

